def bul_dongu(deps: Dict[str, List[str]], kalan: set) -> List[str]:
    """
    Döngü varken, döngüyü oluşturan paketleri bul.
    Döngüdeki paketler: birbirine bağımlı ve hiçbiri kurulamayan paketler.
    """
    # Döngüyü bulmak için DFS
    # Hangi paket hangi paketleri oluşturur? (ters kenarlar)
    olusturur = defaultdict(set)
    for olusturulacak, bagimlilik_listesi in deps.items():
        if olusturulacak not in kalan:
            continue
        for bagimlilik in bagimlilik_listesi:
            if bagimlilik in kalan:
                olusturur[bagimlilik].add(olusturulacak)

    # Döngüyü bulmak için kalan paketlerden birine başla
    # Hangi paketler bu paketi oluşturur?
    def dfs(baslangic: str, yollar: List[str], ziyor: set) -> List[str]:
        # ziyor: şu anda yol üzerinde olan paketler
        # olusturur[baslangic] = baslangic'i oluşturan paketler

        for olusturur_paket in olusturur[baslangic]:
            if olusturur_paket in ziyor:
                # Döngü var! Döngüyü bul
                # ziyor içinde olusturur_paket'ten baslangic'e kadar olan yol
                dongu = []
                for p in ziyor:
                    dongu.append(p)
                dongu.append(baslangic)
                return dongu

            if olusturur_paket in kalan and olusturur_paket != baslangic:
                yollar.append(olusturur_paket)
                result = dfs(olusturur_paket, yollar, ziyor | {olusturur_paket})
                if result:
                    return result
                yollar.pop()

        return None

    # Her kalan paketi dene
    for paket in sorted(kalan):
        result = dfs(paket, [], {paket})
        if result:
            return result

    return []

